WITH enriched AS (SELECT *, DENSE_RANK() OVER (ORDER BY duration_sec DESC NULLS FIRST) AS duration_sec_dense_rank, FIRST_VALUE(duration_sec, TRUE) OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec FROM web_events) SELECT event_type, DATE_TRUNC('MONTH', event_time) AS activity_month, page, COUNT_IF(page = '/cart') AS cart_events, SORT_ARRAY(COLLECT_SET(page)) AS page_list, PERCENTILE_APPROX(duration_sec_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_dense_rank_quartiles, COUNT_IF(page = '/cart') AS cart_events_2, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, PERCENT_RANK() OVER (PARTITION BY event_type ORDER BY COUNT_IF(page = '/cart') DESC) AS cart_events_2_percent_rank FROM enriched GROUP BY event_type, DATE_TRUNC('MONTH', event_time), page HAVING COUNT_IF(page = '/cart') > 1 ORDER BY event_type NULLS LAST;
